import subprocess
q=subprocess.run(['powershell','-NoProfile','-Command',"Get-Process -Name git,git-remote-https,git-pack-objects -ErrorAction SilentlyContinue | Select-Object Id,ProcessName,CPU,WorkingSet64,StartTime | ConvertTo-Json -Compress;$bofSent=0L;$bofRecv=0L;foreach($n in [Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()){$s=$n.GetIPv4Statistics();$bofSent+=$s.BytesSent;$bofRecv+=$s.BytesReceived};Write-Output ('Network totals sent='+$bofSent+' received='+$bofRecv)"],capture_output=True,text=True,encoding='utf-8',errors='replace');print(q.stdout,q.stderr,flush=True)
